// product-runtime/contracts/tenancy-client — INV-T-2876, coordinator ruling INV-Q-3852 (STK-23, ARC-08, ARC-09).
//
// The tenancy-svc fallback client, generated by platform-build's gst.contract-client from tenancy's OpenAPI document in
// the pinned platform-contracts bundle that product-runtime stages (`stageContracts()`). Never hand-edited; its
// classes ship inside product-runtime's impl artefact.
plugins {
    id("gst.contract-client")
}

contractClient { generatorSource("platform-contracts:tenancy:openapi.yaml") }

dependencies {
    implementation(platform(libs.springBoot.dependencies))
    implementation(libs.springWeb)
    implementation(libs.jackson.databind)
    implementation(libs.jackson.moduleKotlin)
}
